#!/usr/bin/env bash
set -euo pipefail

echo "Plaka Kayıt V3.2 Beta güvenlik analizi dosyaları kuruluyor..."

if [[ ! -f app/build.gradle.kts ]]; then
  echo "Hata: Bu komutu PlakaKayit depo ana klasöründe çalıştırmalısın."
  exit 1
fi

python3 - <<'PYFILES'
from pathlib import Path
import base64

files = [
    ('.github/workflows/build-apk.yml', ''),
    ('README.md', ''),
    ('app/build.gradle.kts', ''),
    ('app/src/main/AndroidManifest.xml', ''),
    ('app/src/main/java/com/ogul/plakakayit/MainActivity.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/SecurityActivity.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/data/PlateDatabase.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/data/SecurityModels.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/security/SecurityFrameAnalyzer.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/security/SecurityObjectDetector.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/security/SecurityOverlayView.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/security/SecurityTracker.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/settings/AppPreferences.kt', ''),
    ('app/src/main/java/com/ogul/plakakayit/ui/SecurityEventAdapter.kt', ''),
    ('app/src/main/res/drawable/ic_nav_security.xml', ''),
    ('app/src/main/res/layout/activity_security.xml', ''),
    ('app/src/main/res/layout/item_security_event.xml', ''),
    ('app/src/main/res/menu/bottom_navigation.xml', ''),
    ('app/src/main/res/values/strings.xml', ''),
]

for relative, encoded in files:
    path = Path(relative)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(encoded))
    print(f"Yazıldı: {relative}")
PYFILES

git add .github README.md app
if git diff --cached --quiet; then
  echo "Kodlar zaten V3.2 Beta sürümünde."
else
  git commit -m "Plaka Kayit V3.2: guvenlik ve kisi olay analizi"
  git push origin HEAD:main
fi

echo "V3.2 yüklendi. GitHub Actions APK derlemesini başlattı."
